import { bn } from '@/shared/lib/bn';
import { tr } from '@/shared/lib/i18n';
import { pick, Q, wrongs } from './q';
import type { Generator, LevelBank } from './types';

/* Our own questions for chapter 5 (levels 22–28). First option is always right. */
const n = (v: number) => bn(v);
const d = (v: number) => (v >= 1000 ? bn(v) : bn(Math.round(v * 10) / 10, { grouping: false }));
const mil = (m: number) => (m >= 10 ? `${n(m / 10)} কোটি` : `${n(m * 10)} লাখ`);

const overbook: Generator = {
  id: 'l22-g1', concept: 'overbook',
  make: (rand) => {
    const slots = pick(rand, [100, 250, 400, 1000]), p = pick(rand, [5, 10, 15]);
    const right = Math.floor((slots * (100 + p)) / 100);
    const mult = bn((100 + p) / 100, { grouping: false });
    return {
      prompt: tr(`${n(slots)}টা pickup slot, ${n(p)}% overbook চলবে। সর্বোচ্চ কয়টা booking?`, `${n(slots)} pickup slots with ${n(p)}% overbooking allowed. Maximum bookings?`),
      options: [n(right), ...wrongs(right, [slots, Math.round((slots * p) / 100), slots + p, right + p]).map(n)],
      explain: tr(`${n(slots)} × ${mult} = ${n(right)}; সীমাটা DB constraint-এ রাখুন।`, `${n(slots)} × ${mult} = ${n(right)}; keep the limit in a DB constraint.`),
    };
  },
};
const mailBytes: Generator = {
  id: 'l23-g1', concept: 'attach',
  make: (rand) => {
    const u = pick(rand, [1, 10, 100]), m = pick(rand, [20, 40]), kb = pick(rand, [50, 100]);
    const tb = (u * m * kb) / 1000;
    const opts = wrongs(tb, [tb * 1000, tb / 10, tb * 365]);
    return {
      prompt: tr(`${mil(u)} user, প্রত্যেকে দিনে ${n(m)}টা mail পায়, গড়ে ${n(kb)} KB। দিনে নতুন কত storage?`, `${n(u)} million users each get ${n(m)} mails a day, ${n(kb)} KB on average. New storage a day?`),
      options: [`~${d(tb)} TB`, ...opts.map((o) => `~${d(o)} TB`)],
      explain: tr(`${mil(u)} × ${n(m)} × ${n(kb)} KB ≈ ${d(tb)} TB; বছরে ৩৬৫ গুণ।`, `${n(u)}M × ${n(m)} × ${n(kb)} KB ≈ ${d(tb)} TB; a year is 365 times that.`),
    };
  },
};
const erasure: Generator = {
  id: 'l24-g1', concept: 'domains',
  make: (rand) => {
    const raw = pick(rand, [12, 60, 240]), [k, m] = pick(rand, [[4, 2], [6, 3], [8, 4], [10, 4]] as const);
    const right = Math.round((raw * (k + m)) / k);
    return {
      prompt: tr(`${n(raw)} TB data, erasure coding ${n(k)}+${n(m)}। মোট কত জায়গা লাগে?`, `${n(raw)} TB of data with ${n(k)}+${n(m)} erasure coding. Total space used?`),
      options: [`${n(right)} TB`, ...wrongs(right, [raw * 3, raw, raw * 2, Math.round((raw * m) / k)]).map((o) => `${n(o)} TB`)],
      explain: tr(`প্রতি ${n(k)} ভাগ data-য় ${n(m)} ভাগ parity: ${n(raw)} × ${n(k + m)}/${n(k)} = ${n(right)} TB। তিন কপিতে লাগত ${n(raw * 3)} TB।`, `${n(m)} parity parts per ${n(k)} data parts: ${n(raw)} × ${n(k + m)}/${n(k)} = ${n(right)} TB. Three copies would need ${n(raw * 3)} TB.`),
    };
  },
};
const scatter: Generator = {
  id: 'l25-g1', concept: 'scatter',
  make: (rand) => {
    const s = pick(rand, [4, 8, 16, 32]), k = pick(rand, [10, 100]);
    const right = s * k;
    return {
      prompt: tr(`Rider-রা hash দিয়ে ${n(s)}টা shard-এ। সার্বিক top ${n(k)} পেতে মোট কয়টা entry মেলাতে হয়?`, `Riders are hash-split over ${n(s)} shards. How many entries do you merge for the overall top ${n(k)}?`),
      options: [n(right), ...wrongs(right, [k, s, s + k, right * 2]).map(n)],
      explain: tr(`প্রতিটা shard থেকে top ${n(k)}: ${n(s)} × ${n(k)} = ${n(right)}টা।`, `Each shard sends its top ${n(k)}: ${n(s)} × ${n(k)} = ${n(right)}.`),
    };
  },
};
const fee: Generator = {
  id: 'l26-g1', concept: 'ledger',
  make: (rand) => {
    const x = pick(rand, [500, 1200, 2000, 5000]), f = pick(rand, [1, 2, 3]);
    const cut = (x * f) / 100, right = x - cut;
    const tk = (v: number) => `৳${n(v)}`;
    return {
      prompt: tr(`Customer ${tk(x)} দিল, আমাদের fee ${n(f)}%। Merchant-এর হিসাবে কত credit?`, `A customer pays ${tk(x)} and our fee is ${n(f)}%. How much is credited to the merchant?`),
      options: [tk(right), ...wrongs(right, [x, cut, x + cut]).map(tk)],
      explain: tr(`${tk(x)} debit = ${tk(right)} merchant + ${tk(cut)} fee; দুই দিক সমান।`, `${tk(x)} debit = ${tk(right)} merchant + ${tk(cut)} fee; both sides balance.`),
    };
  },
};
const parts: Generator = {
  id: 'l27-g1', concept: 'tps',
  make: (rand) => {
    const [t, tLabel, tEn] = pick(rand, [[1e6, '১০ লাখ', '1 million'], [5e5, '৫ লাখ', '500,000'], [2e6, '২০ লাখ', '2 million']] as const);
    const p = pick(rand, [10_000, 20_000, 50_000]);
    const right = Math.ceil(t / p);
    return {
      prompt: tr(`লক্ষ্য ${tLabel} TPS, এক partition সেকেন্ডে ${n(p)}টা সামলায়। কয়টা partition?`, `The target is ${tEn} TPS and one partition handles ${n(p)} a second. How many partitions?`),
      options: [n(right), ...wrongs(right, [right * 2, Math.ceil(right / 2), right * 10, right + 7]).map(n)],
      explain: tr(`${tLabel} ÷ ${n(p)} = ${n(right)}; বাস্তবে একটু বাড়তি রাখুন।`, `${tEn} ÷ ${n(p)} = ${n(right)}; keep some spare in practice.`),
    };
  },
};
const nines: Generator = {
  id: 'l28-g1', concept: 'availability',
  make: (rand) => {
    const rows = [
      ['৯৯%', '99%', ['প্রায় ৩.৭ দিন', 'About 3.7 days']],
      ['৯৯.৯%', '99.9%', ['প্রায় ৮.৮ ঘণ্টা', 'About 8.8 hours']],
      ['৯৯.৯৫%', '99.95%', ['প্রায় ৪.৪ ঘণ্টা', 'About 4.4 hours']],
      ['৯৯.৯৯%', '99.99%', ['প্রায় ৫৩ মিনিট', 'About 53 minutes']],
      ['৯৯.৯৯৯%', '99.999%', ['প্রায় ৫ মিনিট', 'About 5 minutes']],
    ] as const;
    const i = Math.floor(rand() * rows.length);
    const [b, e, right] = rows[i]!;
    const others = rows.filter((_, j) => j !== i).map((r) => tr(r[2][0], r[2][1]));
    return {
      prompt: tr(`${b} availability-তে বছরে মোটামুটি কত downtime চলে?`, `Roughly how much downtime a year does ${e} availability allow?`),
      options: [tr(right[0], right[1]), ...others.slice(0, 3)],
      explain: tr(`বছরের ${b} বাদে বাকি অংশ: ${right[0]}।`, `What is left of a year after ${e}: ${right[1].toLowerCase()}.`),
    };
  },
};

